"""Write the kyfram header for one scene from episode.json + src/plan.json.

The agent writes scenes/<Scene>.lgv (shapes only). The timing, banner and caption
cues come from the plan, so retiming a beat never touches scene code, and a scene
file stays identical in shape across episodes.
"""


def lua_str(s):
    return '"' + str(s).replace('\\', '\\\\').replace('"', '\\"') + '"'


def header(ep, scene, scene_frames, fps):
    lines = [
        '// ===== generated by core/tools/render_kyfram.py: do not edit =====',
        f'let SCENE_ID = {lua_str(scene["id"])}',
        f'let BANNER = {lua_str(ep.get("banners", {}).get(scene["id"], ""))}',
        f'let DUR = {scene_frames / fps:.4f}',
        f'let FPSR = {float(fps):.1f}',
    ]
    rows = []
    for w in scene.get('words', []):
        text = w['text'].replace('\\', '\\\\').replace('"', '\\"')
        rows.append('table{w: "%s", f: %d, e: %d}' % (text, w['f'], w['e']))
    lines.append('let CAPS = [' + ', '.join(rows) + ']')
    lines.append('scene(DUR, FPSR)')
    return '\n'.join(lines) + '\n'
